// Everything after the decision starts from the stored lead row, so this workflow can run
// again for a lead that failed half-way (ops replay) without repeating finished steps:
// an email that was already sent is never sent twice.
const row = $input.first().json;
const enrichment = row.enrichment || {};
const scoring = row.scoring || {};
const decision = row.decision || null;
return [{ json: {
  lead: row.lead,
  enrichment: {
    enrichment_status: row.enrichment_status || 'failed',
    enrichment_note: enrichment.note || '',
    profile: enrichment.profile || {},
    sources: enrichment.sources || [],
  },
  scoring: {
    score: row.score, tier: row.tier,
    criteria: scoring.criteria || [], thresholds: scoring.thresholds || {},
  },
  decision,
  outcome: decision ? decision.outcome : 'cold',
  already_sent: Boolean(row.email_sent_at),
  sent_email: row.sent_email || null,
  slack: row.slack_ts ? { channel: row.slack_channel, ts: row.slack_ts } : null,
} }];

// Prepare the approved email. In DEMO_MODE, mail only goes to DEMO_EMAIL_ALLOWLIST
// (addresses or @domains); anything else is redirected to the first allow-listed address,
// with the real recipient shown in the subject, so a demo can never email a real lead.
const f = $('Prepare finish').first().json;
const lead = f.lead;
const decision = f.decision;
const setting = (key, fallback = '') => String($env[key] ?? fallback).trim();
const demo = setting('DEMO_MODE').toLowerCase() === 'true';
const allowlist = setting('DEMO_EMAIL_ALLOWLIST').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const from = setting('EMAIL_FROM');
if (!from) throw new Error('EMAIL_FROM is not set');

let to = lead.email;
let subject = decision.subject;
let redirected_from = null;
if (demo) {
  const allowed = allowlist.some((entry) => entry.startsWith('@')
    ? lead.email.endsWith(entry) : lead.email === entry);
  if (!allowed) {
    const inbox = allowlist.find((entry) => !entry.startsWith('@'));
    if (!inbox) throw new Error('DEMO_MODE is on but DEMO_EMAIL_ALLOWLIST has no address to redirect to');
    redirected_from = lead.email;
    to = inbox;
    subject = `[demo for ${lead.email}] ${subject}`;
  }
}
return [{ json: { from, to, subject, body: decision.body, redirected_from } }];

// Everything the CRM step needs: sent, rejected, timed out or cold. The email is the one
// sent in this run, or the one recorded by an earlier run that failed after sending.
const f = $('Prepare finish').first().json;
const email = $('Record email').isExecuted ? $('Prepare email').first().json : f.sent_email;
return [{ json: {
  lead: f.lead, enrichment: f.enrichment, scoring: f.scoring, decision: f.decision,
  email, outcome: f.outcome,
} }];

// Final status, and the Slack update that replaces the approval request with the outcome.
const f = $('Prepare finish').first().json;
const bundle = $('Bundle for CRM').first().json;
const crm = $input.first().json;
const { lead, scoring, decision, email } = bundle;
const status = {
  approved: 'approved_sent', approved_edited: 'approved_sent', rejected: 'rejected_by_reviewer',
  timeout: 'needs_manual_follow_up', cold: 'cold_recorded',
}[bundle.outcome];

const slackSafe = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const crmText = crm.dry_run ? 'HubSpot update skipped (dry run)' : 'HubSpot updated';
const sentTo = email ? `email sent to ${email.to}${email.redirected_from ? ` (demo redirect for ${email.redirected_from})` : ''}` : '';
const line = {
  approved: `:white_check_mark: Approved by ${decision?.approver} · ${sentTo} · ${crmText}`,
  approved_edited: `:pencil2: Approved with edits by ${decision?.approver} · ${sentTo} · ${crmText}`,
  rejected: `:x: Rejected by ${decision?.approver}: ${decision?.reject_reason} · no email sent · ${crmText}`,
  timeout: `:hourglass: No decision in time · no email sent · manual follow-up task created · ${crmText}`,
  cold: '',
}[bundle.outcome];

let slack = null;
if (f.slack && bundle.outcome !== 'cold') {
  const who = slackSafe(`${lead.name} – ${lead.company || lead.website_domain || 'unknown company'}`);
  const tier = `${scoring.score}/100 ${String(scoring.tier).toUpperCase()}`;
  slack = {
    channel: f.slack.channel, ts: f.slack.ts,
    text: `${who} (${tier}): ${slackSafe(line)}`,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: `*${who}* · ${tier}\n${slackSafe(line)}` } },
      ...(email ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `Subject: ${slackSafe(email.subject)}` }] }] : []),
    ],
  };
}
return [{ json: {
  lead_id: lead.lead_id, status, outcome: bundle.outcome, slack,
  crm: crm.dry_run ? { dry_run: true } : crm,
  dry_actions: crm.dry_run ? crm.dry_actions : [],
} }];

// Not fatal: the email and CRM are done; a failed Slack update is only noted.
const ok = $json.ok === true;
return [{ json: { dry_action: null,
  slack_update: ok ? 'ok' : `failed: ${$json.error?.message || $json.error || 'unknown error'}` } }];
